@{
    var message = "Hello, ASP.NET Core";
    var year = DateTime.UtcNow.Year;
}

<h1>@message</h1>
<p>The current year is @year.</p>
<p>@(2 + 2) equals four.</p>
<p>@(new[] { "Red", "Green", "Blue" }[1]) is the second color.</p>

@{
    var products = new[]
    {
        new { Name = "Laptop", Price = 999.99m },
        new { Name = "Mouse", Price = 25.50m },
        new { Name = "Keyboard", Price = 79.99m }
    };
    var total = products.Sum(p => p.Price);
}

<h2>Product List</h2>
<ul>
@foreach (var product in products)
{
    <li>@product.Name - @product.Price.ToString("C")</li>
}
</ul>

<p>Total inventory value: @total.ToString("C")</p>

@if (total > 1000)
{
    <p class="alert alert-success">High-value inventory detected.</p>
}
else
{
    <p class="alert alert-info">Inventory value is moderate.</p>
}

